import json, hashlib, pathlib
f = json.load(open("tests/fixtures/def835_int02_ontwerpgevallen.json"))
base = pathlib.Path(f["bronbasis"])
for rel, h in f["bronbestanden"].items():
    assert hashlib.sha256((base / rel).read_bytes()).hexdigest() == h, rel
opzet = {g["id"]: g for g in json.load(open(base / "c-codex-app/bewijs/proefopzet-v1.json"))["gevallen"]}
regC = (base / "c-codex-app/casusregister-c-v1.md").read_text()
def check(inv, resp, label):
    if resp is None:
        return
    for p in resp["passages"]:
        ok = inv["kern"][p["start"]:p["end"]] == p["quote"]
        g = p["ground"]
        gok = True
        if g["quote"] is not None:
            gok = inv[g["field"]][g["start"]:g["end"]] == g["quote"]
        print(label, "passage", ok, "ground", gok)
for c in f["gevallen"]:
    items = c.get("versies") or [c]
    for i, v in enumerate(items):
        inv = v["invoer"]
        check(inv, v["modelrespons"], c["id"] + c.get("variant", "") + str(i))
        if inv["kern"] and inv["kern"] != "Toegang:":
            src = [k for k, g in opzet.items() if g["text"] == inv["kern"]]
            print("   kern in proefopzet:", src, "in register C:", inv["kern"] in regC)
            if src:
                g = opzet[src[0]]
                print("   term/bedoeling/context gelijk:", g["term"] == inv["begrip"], g["context"].get("bedoeling") == inv["bedoeling"], g["context"].get("organisatorische_context", []) == inv["organisatorische_context"])
            elif inv["bedoeling"]:
                print("   bedoeling in register C:", inv["bedoeling"] in regC)
