    for p in resp["passages"]:
        ok = inv["kern"][p["start"]:p["end"]] == p["quote"]
        g = p["ground"]
        gok = True
        if g["quote"] is not None:
            gok = inv[g["field"]][g["start"]:g["end"]] == g["quote"]
        print(label, "passage", ok, "ground", gok)
for c in f["gevallen"]:
    items = c.get("versies") or [c]
